sys_ui_action.script:
function confirmStartDeletion() {
    var gm = new GlideModal('', false, 700);
    gm.setTitle('Confirm workload deletion');

    top.window.startWorkloadDeletionConfirm = function(answer) {
        gm.destroy();

        if (answer === 'yes') {
            gsftSubmit(null, g_form.getFormElement(), 'start_workload_deletion');
        }

        return false;
    };

    var html =
        '<div style="padding: 8px 4px 4px 4px; font-size: 16px; line-height: 1.5;">' +
            '<p>Are you sure you want to start the deletion process? This will delete/unpair workloads matched by active deletion sync filters.</p>' +
            '<p>It is recommended to run the following in order before proceeding:<br>' +
            '1. Data Collection - To discover the latest state workloads.<br>' +
            '2. Preview workload deletion - To verify all workloads.</p>' +
            '<p><b>Deletion is a non-reversible action.</b> Click "Yes" to proceed.</p>' +
            '<div style="display:flex; justify-content:flex-end; gap:12px; margin-top:20px;">' +
                '<button style="flex: 1; width: 100%" class="btn btn-default" onclick="top.window.startWorkloadDeletionConfirm(\'no\'); return false;">Cancel</button>' +
                '<button style="flex: 1; width: 100%" class="btn btn-danger" onclick="top.window.startWorkloadDeletionConfirm(\'yes\'); return false;">Yes</button>' +
            '</div>' +
        '</div>';

    gm.renderWithContent(html);
    return false;
}

if (typeof window === 'undefined') {
    var configSysId = current.getUniqueValue();
    var tableName = current.getTableName();
    var redirectUrl = tableName + '.do?sys_id=' + configSysId;

    try {
        var utils = new IllumioUtils();
        var payload = utils.prepareDeletionPayload(configSysId);

        if (!payload.success) {
            gs.addErrorMessage(payload.message);
            action.setRedirectURL(redirectUrl);
        } else if (payload.cancelJob) {
            gs.addErrorMessage(payload.message);
            action.setRedirectURL(redirectUrl);
        } else {
            // Check for running jobs
            var runningJobs = new GlideAggregate('x_illu2_illumio_illumio_scheduled_jobs');
            runningJobs.addQuery('job_status', 'running');
            runningJobs.addQuery('illumio_pce_configuration', configSysId);
            runningJobs.addAggregate('COUNT');
            runningJobs.query();
            if (runningJobs.next() && parseInt(runningJobs.getAggregate('COUNT')) > 0) {
                gs.addErrorMessage('Another job is already running for this PCE Configuration. Please wait for it to complete.');
                action.setRedirectURL(redirectUrl);
            } else {
                var scheduledJobGr = new GlideRecordSecure('x_illu2_illumio_illumio_scheduled_jobs');
                scheduledJobGr.initialize();
                scheduledJobGr.job_owner = gs.getUser().getID();
                scheduledJobGr.job_type = 'deletion';
                scheduledJobGr.job_status = 'running';
                scheduledJobGr.job_started = new GlideDateTime();
                scheduledJobGr.current_operation = 'Preparing workload deletion';
                scheduledJobGr.illumio_pce_configuration = configSysId;

                var logTimestamp = new Date(new GlideDateTime().getNumericValue()).toISOString();
                var logs = '[' + logTimestamp + '] Deletion started: ' + payload.deletionCount + ' workload(s) for deletion, ' + payload.unpairCount + ' workload(s) for unpair';
                if (payload.skippedCount > 0) {
                    logs += ', ' + payload.skippedCount + ' skipped';
                }
                if (payload.thresholdExceeded) {
                    logs += '\n[' + logTimestamp + '] Deletion threshold limit exceeded. Some workloads were not included.';
                }
                scheduledJobGr.logs = logs;
                var jobSysId = scheduledJobGr.insert();

                if (gs.nil(jobSysId)) {
                    gs.addErrorMessage('Failed to create scheduled job for deletion.');
                    action.setRedirectURL(redirectUrl);
                } else {
                    var pceConfig = new IllumioGetPCEConfiguration().getConfiguration(configSysId);

                    var parameters = {
                        jobSysId: jobSysId,
                        operation: 'delete',
                        partialSucc: payload.thresholdExceeded ? 'true' : 'false',
                        skipped: payload.skippedCount + '',
                        workloads_to_delete: JSON.stringify(payload.retiredWorkloads),
                        vens_to_unpair: JSON.stringify(payload.vensToUnpair),
                        pce_url: pceConfig.pceUrl,
                        pce_secret: pceConfig.pceSecret,
                        pce_username: pceConfig.pceUsername,
                        pce_org_id: pceConfig.pceOrganizationID + '',
                        pce_authorization: gs.base64Encode(pceConfig.pceUsername + ':' + pceConfig.pceSecret),
                        configSysId: configSysId,
                        time_zone: gs.getSession().getTimeZoneName(),
                        batch_size: gs.getProperty('x_illu2_illumio.bulk_operation_batch_size', 1000),
                        enable_pce_mid_proxy: pceConfig.enable_pce_mid_proxy,
                        retry_params: JSON.stringify(pceConfig.retry_params)
                    };

                    var eccQueue = new IllumioAddToECCQueue('IllumioUpdateWorkloads', pceConfig.midServer, parameters);
                    var dispatched = eccQueue.insert();

                    if (dispatched) {
                        gs.addInfoMessage('Deletion process started. ' + payload.deletionCount + ' workload(s) for deletion, ' + payload.unpairCount + ' for unpair. Track progress in Scheduled Jobs.');
                    } else {
                        scheduledJobGr.get(jobSysId);
                        scheduledJobGr.job_status = 'failed';
                        scheduledJobGr.job_completed = new GlideDateTime();
                        scheduledJobGr.logs += '\n[' + new Date(new GlideDateTime().getNumericValue()).toISOString() + '] Failed to dispatch deletion to MID server';
                        scheduledJobGr.update();
                        gs.addErrorMessage('Failed to dispatch deletion to MID server.');
                    }
                    action.setRedirectURL(redirectUrl);
                }
            }
        }
    } catch (ex) {
        gs.error('[StartWorkloadDeletion] Exception: ' + ex);
        gs.addErrorMessage('Error preparing deletion: ' + ex);
        action.setRedirectURL(redirectUrl);
    }
}
